function makeFancyString(s) {
  const result = [];
  for (const ch of s) {
    const size = result.length;
    if (size >= 2 && result[size - 1] === ch && result[size - 2] === ch) {
      continue;
    }
    result.push(ch);
  }
  return result.join('');
}

