function makeFancyString(s) {
  let text = s;
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + 2 < text.length; i++) {
      if (text[i] === text[i + 1] && text[i + 1] === text[i + 2]) {
        text = text.slice(0, i) + text.slice(i + 1);
        changed = true;
        break;
      }
    }
  }
  return text;
}

