function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const target = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 14);
  let s = '';
  while (s.length < target) {
    const ch = letters[Math.floor(rand() * letters.length)];
    const run = 1 + Math.floor(rand() * (size === 'large' ? 8 : 5));
    s += ch.repeat(Math.min(run, target - s.length));
  }
  return [s];
}
